import{_ as p,a0 as o,w as r,s as d,I as t,x as a,a1 as i,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170308 How to Reset MySQL or MariaDB Root Password in Linux","title":"如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码","tag":"201703","desc":""},"relativePath":"201703/20170308 How to Reset MySQL or MariaDB Root Password in Linux.md","filePath":"[post].md"}'),m={name:"201703/20170308 How to Reset MySQL or MariaDB Root Password in Linux.md"};function u(g,s,b,y,h,k){const n=o("Link");return r(),d("div",null,[s[18]||(s[18]=t("h1",{id:"如何在-linux-中重置-mysql-或者-mariadb-的-root-密码",tabindex:"-1"},[a("如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码 "),t("a",{class:"header-anchor",href:"#如何在-linux-中重置-mysql-或者-mariadb-的-root-密码","aria-label":"Permalink to “如何在 Linux 中重置 MySQL 或者 MariaDB 的 root 密码”"},"​")],-1)),s[19]||(s[19]=t("p",null,[a("如果你是第一次设置 MySQL 或 MariaDB 数据库，你可以直接运行 "),t("code",null,"mysql_secure_installation"),a(" 来实现基本的安全设置。")],-1)),s[20]||(s[20]=t("p",null,"其中一项是设置数据库 root 帐户的密码 - 你必须保持私密，并仅在绝对需要时使用。如果你忘记了密码或需要重置密码（例如，当数据库管理员换人或被裁员！），这篇文章会派上用场。我们将解释如何在 Linux 中重置或恢复 MySQL 或 MariaDB 的 root 密码。",-1)),t("p",null,[s[1]||(s[1]=t("strong",null,"建议阅读：",-1)),s[2]||(s[2]=a(" [更改 MySQL 或 MariaDB 的 root 密码] ",-1)),i(n,{href:"http://www.tecmint.com/change-mysql-mariadb-root-password/"},{default:e(()=>[...s[0]||(s[0]=[a("1",-1)])]),_:1}),s[3]||(s[3]=a("。",-1))]),s[21]||(s[21]=l(`<p>虽然我们将在本文中使用 MariaDB，但这些说明同样也适用于 MySQL。</p><h3 id="恢复-mysql-或者-mariadb-的-root-密码" tabindex="-1">恢复 MySQL 或者 MariaDB 的 root 密码 <a class="header-anchor" href="#恢复-mysql-或者-mariadb-的-root-密码" aria-label="Permalink to “恢复 MySQL 或者 MariaDB 的 root 密码”">​</a></h3><p>开始之前，先停止数据库服务并检查服务状态，我们应该可以看到先前设置的环境变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- SystemD ------------- </span></span>
<span class="line"><span># systemctl stop mariadb</span></span>
<span class="line"><span>------------- SysVinit -------------</span></span>
<span class="line"><span># /etc/init.d/mysqld stop</span></span></code></pre></div><p>接下来，用 <code>--skip-grant-tables</code> 选项启动服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- SystemD ------------- </span></span>
<span class="line"><span># systemctl set-environment MYSQLD_OPTS=&quot;--skip-grant-tables&quot;</span></span>
<span class="line"><span># systemctl start mariadb</span></span>
<span class="line"><span># systemctl status mariadb</span></span>
<span class="line"><span>------------- SysVinit -------------</span></span>
<span class="line"><span># mysqld_safe --skip-grant-tables &amp;</span></span></code></pre></div>`,6)),t("p",null,[i(n,{href:"http://www.tecmint.com/wp-content/uploads/2017/03/Start-MySQL-with-Skip-Tables.png"},{default:e(()=>[...s[4]||(s[4]=[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/03/Start-MySQL-with-Skip-Tables.png",alt:"Start MySQL/MariaDB with Skip Tables"},null,-1)])]),_:1})]),s[22]||(s[22]=l(`<p><em>使用 skip tables 启动 MySQL/MariaDB</em></p><p>这可以让你不用 root 密码就能连接到数据库（你也许需要切换到另外一个终端上）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mysql -u root</span></span></code></pre></div><p>接下来，按照下面列出的步骤来。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MariaDB [(none)]&gt; USE mysql;</span></span>
<span class="line"><span>MariaDB [(none)]&gt; UPDATE user SET password=PASSWORD(&#39;YourNewPasswordHere&#39;) WHERE User=&#39;root&#39; AND Host = &#39;localhost&#39;;</span></span>
<span class="line"><span>MariaDB [(none)]&gt; FLUSH PRIVILEGES;</span></span></code></pre></div><p>最后，停止服务，取消环境变量设置并再次启动服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- SystemD ------------- </span></span>
<span class="line"><span># systemctl stop mariadb</span></span>
<span class="line"><span># systemctl unset-environment MYSQLD_OPTS</span></span>
<span class="line"><span># systemctl start mariadb</span></span>
<span class="line"><span>------------- SysVinit -------------</span></span>
<span class="line"><span># /etc/init.d/mysql stop</span></span>
<span class="line"><span># /etc/init.d/mysql start</span></span></code></pre></div><p>这可以让先前的改变生效，允许你使用新的密码连接到数据库。</p><h5 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h5><p>本文我们讨论了如何重置 MariaDB/MySQL 的 root 密码。一如往常，如果你有任何问题或反馈请在评论栏中给我们留言。我们期待听到你的声音。</p><hr><p>作者简介：</p><p>Gabriel Cánepa - 一位来自阿根廷圣路易斯梅塞德斯镇 (Villa Mercedes, San Luis, Argentina) 的 GNU/Linux 系统管理员，Web 开发者。就职于一家世界领先级的消费品公司，乐于在每天的工作中能使用 FOSS 工具来提高生产力。</p><hr>`,14)),t("p",null,[s[6]||(s[6]=a("via: ",-1)),i(n,{href:"http://www.tecmint.com/reset-mysql-or-mariadb-root-password/"},{default:e(()=>[...s[5]||(s[5]=[a("http://www.tecmint.com/reset-mysql-or-mariadb-root-password/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),i(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:e(()=>[...s[7]||(s[7]=[a("Gabriel Cánepa",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[8]||(s[8]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),i(n,{href:"https://github.com/jasminepeng"},{default:e(()=>[...s[9]||(s[9]=[a("jasminepeng",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const f=p(m,[["render",u]]);export{L as __pageData,f as default};
